pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Reward tight fits (near-perfect packing).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Reward residual that can still host a typical future item.
    if post_residual >= 10 {
        score -= 10.0;
    } else {
        score += 10.0; // dead space below min item size is pure waste
    }

    // Last-chance pressure: if this is the only fitting bin, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor filling.
    score += 0.8 * open_bins_count as f64;

    // Mean residual coupling: prefer bins below the mean residual (tighter bins)
    // to consolidate packing.
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Lookahead: if the next item fits exactly in the post-residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= 15.0 * (1.0 - gap as f64 / 10.0);
        } else {
            score -= 5.0;
        }
    }
    // If next item cannot fit in the leftover, the leftover risks becoming dead space.
    if next_item_size > post_residual && post_residual > 0 {
        score += 8.0;
    }

    // New-bin candidate handling: an empty bin should only win when no open bin
    // offers a good fit. Give it a mild baseline plus a bonus when open bins are scarce.
    if bin_residual == bin_capacity {
        score += 12.0 - 1.5 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 30.0; // must open a new bin anyway
        }
    }

    // Late-stream consolidation: near the end, prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fill_ratio = 1.0 - pr / cap;
    let mut score = pr * 0.76 + (pr * 0.95 + fill_ratio * 0.05) * 0.24;

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Dead-space bands (harmonic classes).
    if post_residual > 0 && post_residual <= 9 {
        score += 120.0;
    } else if post_residual <= 19 {
        score += 45.0;
    } else if post_residual <= 29 {
        score += 12.0;
    } else if post_residual >= 50 {
        score -= 25.0;
    }

    // Two-step lookahead with the next item.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size < post_residual {
            let fill = next_item_size as f64 / pr;
            score -= 80.0 * fill;
            let post2 = post_residual - next_item_size;
            if post2 > 0 && post2 <= 9 {
                score += 60.0;
            }
            // chain bonus: near-exhaustion after next item on well-filled bins
            if post2 >= 1 && post2 <= 8 && fill_ratio > 0.45 {
                score -= 2.5 * (1.0 - post2 as f64 / 8.0) * fill_ratio;
            }
            // multiplicative reuse: residual is a multiple of the small next item
            if next_item_size <= 10 && post_residual % next_item_size == 0 {
                score -= 3.0;
            }
        } else {
            score += 30.0 + 2.0 * (100 - post_residual.min(100)) as f64;
            // crowded stream: penalize unusable residuals harder
            if fill_ratio > 0.5 && open_bins_count > 6 {
                score += 3.5 * fill_ratio;
            }
        }
    } else {
        score -= 13.0;
    }

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        score += 16.0;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 14.0;
        if next_item_size > 0 {
            let pair = item_size + next_item_size;
            if pair == bin_capacity {
                score -= 104.0;
            } else if pair >= bin_capacity.saturating_sub(5) {
                score -= 62.0;
            } else if pair >= bin_capacity.saturating_sub(18) {
                score -= 25.0;
            } else {
                score += 9.0;
            }
        }
        if progress > 0.66 {
            score += 26.0 * progress;
        }
        if mean_residual > 40.0 && open_bins_count > 3 {
            score += 50.0;
        }
        if fitting_bins_count == 0 {
            score += 12.0;
        }
        if next_item_size > 0 && (next_item_size as f64) >= cap * 0.5 && fitting_bins_count > 0 {
            score -= 20.0;
        }
    } else {
        // Residual-balance preference toward the mean.
        if pr < mean_residual {
            score += (mean_residual - pr) * 0.27;
        } else {
            score -= (pr - mean_residual) * 0.09;
        }

        // Tight-fit lookahead: how close the next item brings the bin to full.
        if next_item_size > 0 && (next_item_size as f64) <= pr {
            let tight = (pr - next_item_size as f64) / cap;
            if tight < 0.05 {
                score -= 13.5;
            } else if tight < 0.12 {
                score -= 5.5;
            }
        }

        // Unusable-residual penalties scaled by fill ratio.
        if fill_ratio > 0.55 && next_item_size > 0 && (next_item_size as f64) > pr {
            score += 12.5 * fill_ratio;
        }
        if fill_ratio > 0.7 && next_item_size > 0 && (next_item_size as f64) > pr {
            score += 8.0;
        }
        if fill_ratio > 0.85 && next_item_size > 0 && (next_item_size as f64) <= pr {
            score -= 6.0 * fill_ratio;
        }

        // Consolidation pressure late in stream with many open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress > 0.7 && fill_ratio > 0.4 && next_item_size > 0 && (next_item_size as f64) <= pr {
            let chain = pr - next_item_size as f64;
            if chain < 4.0 {
                score -= 5.0 * progress;
            }
        }
    }

    // Modulo-structure bonus.
    if post_residual > 0 {
        if post_residual % 10 == 0 {
            score -= 15.0;
        } else if post_residual % 5 == 0 {
            score -= 5.0;
        }
    }

    score * 0.93 + fill_ratio * 0.07
}

