        if next_item_size > 0 && next_item_size >= item_size {
            // Large next item: a fresh bin preserves room.
            score -= 25.0;
        }
    }

    // Mild penalty for many open bins (encourage consolidation).
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: prefer low post-residual, with smooth polynomial shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Non-linear coupling of post-residual with stream progress:
    // early on, waste tolerance is higher; late, tighten packing
    score += pr * (0.5 * progress + 1.5 * progress * progress) * (norm_pr * (1.0 - norm_pr)) * 4.0;

    // Reward tight fits (small post-residual) more strongly as stream advances
    score -= (cap - pr) * progress * progress * 0.3;

    // Penalize dead space that cannot fit the next item (smooth interaction)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let deficit = (nxt - pr).max(0.0) / cap;
        score += deficit * deficit * cap * (0.4 + 0.6 * progress);
        // Bonus if this placement leaves room for the lookahead item
        let slack_fit = (pr - nxt).max(0.0) / cap;
        score -= slack_fit * cap * (0.25 + 0.35 * progress);
    }

    // Last-chance bin: smooth reward to use it rather than open a new one
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - progress * 0.5);
    }

    // Mild penalty for spreading across many open bins, scaled by progress
    score += open_bins_count as f64 * (0.5 + 1.0 * progress);

    // Pull toward mean residual: avoid extreme outliers smoothly
    score += 0.3 * (pr - mean_residual).abs() * (0.5 + progress);

    // New-bin candidate: penalize slightly more as stream progresses unless item is huge
    if bin_residual == bin_capacity {
        score += 8.0 + 10.0 * progress - 6.0 * norm_item * norm_item;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residue modulo capacity quartiles.
    let q = bin_capacity / 4; // 25
    let class = post_residual / q; // 0..4 harmonic class

    // Reward small post_residual (tight fit), but discretize into harmonic bands
    // so near-equal fits within a band are ranked by exact leftover.
    score = score * (1.0 + 0.15 * class as f64);

    // Dead-space penalty: post_residual smaller than the smallest possible item (1)
    // is perfect; post_residual in awkward low band (1..q/2) is nearly dead space.
    if post_residual > 0 && post_residual < q / 2 {
        score += 12.0; // awkward sliver
    }
    if post_residual == 0 {
        score -= 20.0; // perfect closure
    }

    // Lookahead coupling: harmonic class of next item vs post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits exactly into this bin's future residual:
            let nxt_class = next_item_size / q;
            score -= (3.0 + nxt_class as f64) * (post_residual - next_item_size) as f64;
        } else {
            score += 4.0; // lookahead cannot use the leftover
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin gets a moderate default so that
    // only genuinely bad fits in open bins trigger opening a new bin.
    if bin_residual == bin_capacity {
        score = (bin_capacity as f64) * 0.5 + (open_bins_count as f64).sqrt() * 2.0;
        if next_item_size > 0 && next_item_size > item_size {
            score -= 5.0; // reserve fresh space for larger follow-up items
        }
        // late in the stream, prefer closing existing bins over spawning
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.8 {
            score += 10.0;
        }
    }

    // Slight global pressure: many open bins with high mean residual -> prefer
    // packing into existing bins (penalize new-bin tendency implicitly).
    if mean_residual > (bin_capacity as f64) * 0.5 && bin_residual < bin_capacity {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (<10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Penalize bins with large residual relative to capacity (prefer tight packing).
    let residual_ratio = post_residual as f64 / bin_capacity as f64;
    score += residual_ratio * 20.0;

    // Open bins pressure: with many open bins, favor filling existing bins over opening new ones.
    let open_pressure = open_bins_count as f64 / (total_items.max(1) as f64).sqrt();
    score += if bin_residual == bin_capacity {
        open_pressure * 15.0 // opening a new bin is penalized when many bins are open
    } else {
        -open_pressure * 2.0
    };

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 && (post_residual as i64 - next_item_size as i64) >= 0 {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 5.0; // next item won't fit -> risk of dead space
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score += (mean_residual - post_residual as f64) * 0.5;

    // Progression: later in stream, be more conservative about dead space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core 2-step lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect chain: post residual exactly matches next item -> big reward.
            let slack = post_residual as f64 - next_item_size as f64;
            score -= 20.0 + 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Dead space penalty grows when post-residual is too small for next item.
            score += 4.0 + 6.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        }
    }

    // Reward tight fits relative to mean residual across open bins.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 8.0;

    // Penalize bins far above the mean residual (fragmented bins) mildly.
    let dev = post_residual as f64 - mean_residual;
    if dev > 0.0 {
        score += 0.05 * dev;
    } else {
        score += 0.02 * dev; // slightly reward below-mean residuals
    }

    // Last-chance bin: strong incentive to use it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are poor fits.
    if bin_residual == bin_capacity {
        score += 25.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // fresh bin still chains well
        }
        if fitting_bins_count <= 1 {
            score -= 30.0; // no good alternative exists, allow new bin
        }
    }

    // Late in the stream: prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count > 1 {
        score += progress * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly prefer bins that end with little waste.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 60.0 * tightness * tightness;
    }

    // Penalize dead space that is too small for any plausible future item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            score -= 0.5 * next_item_size as f64;
        } else {
            // Next item won't fit here; penalize proportionally to the wasted gap.
            score += 0.3 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // Crowding: prefer bins in less crowded regimes; encourage consolidation
    // when many bins are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // Prefer bins whose residual is below the mean (compact bins absorb items,
    // leaving roomy bins for future large items).
    score += 0.4 * (bin_residual as f64 - mean_residual).max(0.0)
           - 0.2 * (mean_residual - bin_residual as f64).max(0.0);

    // New-bin candidate: neutral base so it's chosen only when open bins score badly.
    if bin_residual == bin_capacity {
        score = 100.0 + 0.1 * item_size as f64 - 20.0 * progress;
        // If the item barely fits nowhere else, opening a bin is fine.
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64 / cap;
    let it = item_size as f64 / cap;

    // Base: prefer small post residual (tight fit), with smooth non-linear shaping
    let mut score = pr * (1.0 + 0.8 * pr * (1.0 - pr));

    // Non-linear coupling of item size with stream progress:
    // late in the stream, large items packing tightly matter more
    score += 0.6 * it * it * (1.0 - progress) * pr;

    // Penalize dead space that is too small to be useful later (smooth barrier near 0)
    let dead = (pr - 0.08) / (1.0 + (pr - 0.08).abs());
    score += 1.2 * (1.0 - dead) * pr;

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 {
        score -= 2.5 * (1.0 - pr);
    }

    // Prefer bins whose residual deviates favorably from the mean (balance-aware)
    let mean_norm = mean_residual / cap;
    score += 0.4 * (pr - mean_norm) * (pr - mean_norm);

    // Lookahead: if next item fits exactly in post residual, reward
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let gap = (pr - nx).abs();
        score -= 0.9 * (1.0 - gap) * (1.0 - gap) * (1.0 - pr);
    }

    // Early stream: mildly discourage opening too many bins
    score += 0.5 * progress * (1.0 - progress) * pr * (open_bins_count as f64).sqrt() * 0.1;

    // New-bin candidate handling: only attractive when nothing fits well
    let is_new = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new {
        score += 1.5 - 1.5 * progress + 2.0 * (fitting_bins_count as f64).recip();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post-fit residual (capacity fractions) ---
    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Fractional class of post_residual relative to capacity.
    let frac = post_residual as f64 / bin_capacity as f64;
    // Dead-space penalty grows quadratically once residual drops below half.
    if frac < 0.5 {
        score += (0.5 - frac) * (0.5 - frac) * 120.0;
    }

    // Integer-division threshold classes: residuals in [1,10] are nearly
    // unusable dead space; strongly penalize creating them.
    let small_class = post_residual / 10; // 0 => 1..10 residual
    if small_class == 0 {
        score += 60.0;
    }

    // --- Harmonic compatibility with the lookahead item (modulo logic) ---
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item fits here: reward, scaled by how snugly it fits.
            let next_left = post_residual - next_item_size;
            score -= 25.0;
            if next_left / 10 == 0 {
                // next item fills this bin almost exactly afterwards
                score -= 30.0;
            }
        } else {
            // Next item cannot use this residual: penalize by unusable gap.
            score += (next_item_size - post_residual) as f64 * 0.5;
            // If next item would exactly fill some capacity fraction
            // (next_item_size is a harmonic divisor of capacity), opening
            // a fresh bin for it is attractive; discourage wasting this bin.
            if bin_capacity % next_item_size == 0 {
                score += 15.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Mild preference to fill crowded state: many open bins with low mean
    // residual -> consolidate rather than open new bins.
    if bin_residual < bin_capacity {
        score -= 5.0;
        if (mean_residual - bin_residual as f64).abs() < 10.0 {
            score -= 3.0;
        }
    }

    // New-bin candidate (empty bin): make it unattractive unless the fit
    // here would create severe dead space. Base penalty for opening new bin.
    if bin_residual == bin_capacity {
        score += 80.0;
        // But allow new bin if placing here leaves a very small residual
        // that no plausible next item (>=10) could use.
        if post_residual < 10 && post_residual > 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold the smallest
    // plausible item (1..100 range, but conservatively < 10) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // unusable sliver => heavy penalty
    }

    // Tight fits are excellent: reward near-zero usable post_residual.
    if post_residual == 0 {
        score -= 25.0; // perfect fill
    } else if post_residual <= 15 {
        score -= 10.0; // likely still usable for small items
    }

    // Penalize mid-range wasted gaps proportionally (quadratic dead-space tax).
    if post_residual > 15 {
        let waste = post_residual as f64 - 15.0;
        score += 0.08 * waste * waste;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Open-bin pressure: with many open bins, discourage opening another.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure that grows with open bins.
        score = bin_capacity as f64 * 0.6
            + 6.0 * open_bins_count as f64
            + 20.0 * progress
            - (mean_residual * 0.3);
        // If the next item would fit nicely in this fresh bin, soften slightly.
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 2.0;
        }
    } else {
        // Prefer bins whose residual is close to what we consume (good packing).
        let tightness = (bin_residual as f64 - item_size as f64).abs();
        score += 0.05 * tightness;
        // Lookahead: if the next item fits the post_residual exactly, reward.
        if next_item_size > 0 && next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            // Next item cannot use the leftover: mild dead-space penalty.
            score += 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward if next item fits the post residual exactly or well.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // Perfect 2-item completion of this bin: very desirable.
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportional to how much space remains after both.
            let second_post = post_residual - next_item_size;
            score -= 30.0 - (second_post as f64) * 0.4;
        } else {
            // Next item does NOT fit: bin will be closed with dead space post_residual.
            // Penalize if post_residual is too small to ever be useful (below min item size).
            if post_residual < 10 {
                score += 25.0;
            } else {
                score += (post_residual as f64).min(20.0) * 0.3;
            }
        }
    } else {
        // Last item: prefer tightest fit overall.
        score -= 10.0;
    }

    // Compare post_residual against mean residual across open bins:
    // leaving a residual far below mean creates an outlier dead space.
    let pr = post_residual as f64;
    if pr < mean_residual {
        score += (mean_residual - pr) * 0.15;
    } else {
        score -= (pr - mean_residual) * 0.05;
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New empty bin candidate: neutral-ish baseline; only chosen when open bins score badly.
    if bin_residual == bin_capacity {
        score += 12.0;
        // If the current item plus next item would nearly fill a fresh bin, encourage opening.
        if next_item_size > 0 && (item_size + next_item_size) >= bin_capacity - 5 {
            score -= 40.0;
        }
        // Avoid opening new bins late in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Prefer filling bins with larger residuals when many bins are open (consolidation).
    score -= (bin_residual as f64) * 0.02 * (open_bins_count.min(20) as f64) / 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let fit_ratio = item_size as f64 / bin_residual as f64;
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    score -= 30.0 * (fit_ratio * fit_ratio);

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 {
        let dead = if post_residual < 10 { 1.0 } else { 0.0 };
        score += 40.0 * dead;
    }

    // Lookahead: if next item fits post-residual, reward this bin.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && next_item_size > post_residual as u32 {
        score += 8.0;
    }

    // Last-chance bonus: only fitting bin, avoid opening new bin unless fit is bad.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * fit_ratio;
    }

    // New-bin candidate handling: prefer new bin only when fit is poor
    // or stream is early and item is large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = fit_ratio < 0.45;
        let early = progress < 0.25;
        if poor_fit || early {
            score -= 20.0;
        } else {
            score += 25.0;
        }
    }

    // Global state: many open bins with high mean residual -> reuse bins.
    let spread = mean_residual - post_residual as f64;
    if open_bins_count > 4 && spread > 0.0 {
        score -= 5.0;
    } else if spread < -10.0 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_r = r / cap;

    // Base: penalize wasted space, with a non-linear (quadratic) dead-space cost
    let mut score = r + 40.0 * norm_r * norm_r * cap;

    // Smooth stream-progress coupling: later in the stream, waste matters more
    score *= 1.0 + 0.6 * progress * norm_r;

    // Reward tight fits: low post residual relative to item size
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * (1.0 - norm_r);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits the post residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= r {
        score -= 10.0 * (1.0 - r / cap);
    }

    // Penalize bins far below mean residual (keeps residual distribution balanced)
    score += 0.15 * (mean_residual - r).abs();

    // Slight preference for fewer open bins when residuals are similar
    score += 0.01 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual lies in a "usable"
    // class (divisible into common small item sizes) are preferred.
    let pr = post_residual;
    let class_bonus: f64 = if pr == 0 {
        -40.0 // perfect fit: strongest reward
    } else if pr <= 5 {
        20.0 // tiny dead space, nearly useless
    } else if pr % 10 == 0 {
        -12.0 // residual re-usable by decade-sized items
    } else if pr % 5 == 0 {
        -6.0
    } else if pr % 2 == 0 {
