pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Normalized post-residual, base of polynomial coupling
    let x = pr / cap; // in [0,1]

    // Non-linear polynomial coupling with stream progress:
    // early on, prefer filling bins tightly (low post_residual weighted strongly);
    // later, dead space matters less, so the cubic term relaxes.
    let poly = x * x * (3.0 - 2.0 * x); // smoothstep in [0,1]
    score += poly * (1.0 - progress) * cap * 0.6;

    // Reward tight fits (small post_residual) super-linearly
    score -= (1.0 - x).powi(3) * 8.0;

    // Penalize leaving dead space that no plausible item can use
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            // wasted space: cannot host the lookahead item
            score += (nx - pr) * (0.5 + 0.5 * (1.0 - progress));
        } else {
            // bonus for still accommodating the next item
            score -= (pr - nx).min(cap) * 0.05;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - progress);
    }

    // New-bin candidate: encourage deferring new bins while open bins are loose,
    // but allow opening one when open bins are nearly full on average.
    let mean_x = mean_residual / cap;
    if bin_residual == bin_capacity {
        // Empty bin: score relative to mean residual of open bins.
        // Attractive if existing bins are crowded (low mean residual).
        score = cap * (0.35 + 0.5 * mean_x) - 10.0 * (1.0 - progress) * (1.0 - mean_x);
    } else {
        // Mild penalty when this bin's residual is far below the mean (already tight)
        score += ((mean_x - x).max(0.0)) * cap * 0.3;
    }

    // Slight preference to spread across many open bins when they are numerous and loose
    score += (open_bins_count as f64).ln().max(0.0) * x * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: leftovers that are "nice" fractions
    // of capacity (0, small, or exactly matching common item sizes) are valuable;
    // awkward mid-range leftovers are dead space and should be penalized.
    let pr = post_residual;
    let class: f64 = if pr == 0 {
        -40.0 // perfect closure, strongly reward
    } else {
        match pr % 10 {
            0 => -8.0,                       // round leftover, reusable
            1..=9 => ((pr % 10) as f64) * 0.6, // ragged edge penalty
            _ => 0.0,
        }
    };
    score += class;

    // Quadratic dead-space pressure: mid-sized residuals (~30-60) are the least
    // useful for future items drawn from 1..100; extremes are fine.
    let x = pr as f64 / cap;
    score += 25.0 * x * (1.0 - x) * 4.0 * x * (1.0 - x); // peaks near x=0.5

    // Lookahead: reward bins whose leftover can host the next item (harmonic fit).
    if next_item_size > 0 && post_residual >= next_item_size {
        let snug = (post_residual - next_item_size) as f64;
        score -= 12.0 + 10.0 * (1.0 - snug / cap);
        // exact harmonic pairing (leftover == next item) is gold
        if post_residual == next_item_size {
            score -= 30.0;
        }
    } else if next_item_size > 0 {
        // leftover cannot host next item: mild penalty scaled by how far off
        score += 4.0 * (next_item_size - post_residual) as f64 / cap;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Penalize opening a new bin unless the current item leaves a terrible
    // fit in every existing bin (i.e. this is effectively a fresh start).
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / cap;
        // Opening is attractive only for large items that would fragment a bin badly.
        score += 55.0 - 45.0 * tightness;
        // Early in the stream, keep bins open longer (amortization).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * (1.0 - progress);
        // Many open bins => discourage spreading; few => allow a fresh bin.
        score += (open_bins_count as f64).sqrt() * 3.0;
    }

    // Prefer packing into bins tighter than the current mean residual
    // (consolidation of fragments into harmonic groups).
    score += 0.15 * (mean_residual - bin_residual as f64).max(-50.0).min(50.0);

    // Fine modular tiebreak on item size class (decile harmony).
    score += ((item_size % 10) as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to fit any
    // plausible future item (min item = 1, but practically small gaps < 10)
    // are pure waste. Penalize hard when post_residual falls in the dead zone.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 40.0; // unusable sliver
        } else if post_residual < 20 {
            score += 15.0; // marginal gap, likely waste
        } else if post_residual < 35 {
            score += 5.0; // moderate waste risk
        }
    } else {
        // Perfect fit: strongly reward closing a bin exactly.
        score -= 60.0;
    }

    // Reward tight fits: fraction of bin consumed by this placement.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * tightness;

    // Lookahead: if the next item fits exactly into the post_residual,
    // this placement is excellent (chain fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here: gap becomes dead space for lookahead
            score += 8.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing ones rather than spreading; penalize more open bins context.
    score += 0.6 * open_bins_count as f64;

    // Mean residual coupling: if this bin's residual is far below the mean
    // (a laggard bin), prefer filling it to reduce fragmentation.
    let residual_gap = mean_residual - post_residual as f64;
    score -= 0.3 * residual_gap;

    // New-bin candidate handling: an empty bin is a fallback. Make it
    // moderately attractive only when no open bin fits well, i.e. when
    // item is large relative to typical residuals. Bias it slightly worse
    // than a good existing fit, better than a terrible one.
    if bin_residual == bin_capacity {
        // opening a new bin costs a full bin: penalize baseline
        score += 30.0;
        // but if the item is huge, a fresh bin is the right call
        if item_size >= 60 {
            score -= 35.0;
        }
        // late in the stream, prefer reusing open bins harder
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits (tight packing).
    if post_residual < 5 {
        score -= 60.0;
    } else if post_residual < 15 {
        score -= 25.0;
    }

    // Two-step lookahead: reward bins whose post_residual matches next_item_size well.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if gap <= 2.0 {
            score -= 40.0; // next item fills this bin exactly
        } else if gap <= 10.0 {
            score -= 18.0;
        } else if post_residual < next_item_size as f64 {
            // next item can't fit here; dead space unless residual is tiny
            score += 8.0;
        }
        // Prefer leaving residuals that are either ~0 or large enough to be reusable
        if post_residual > 0 && post_residual < 10 && post_residual < next_item_size {
            score += 15.0; // small stranded sliver
        }
    }

    // Compare against mean residual: penalize bins far below the mean (they become waste),
    // mildly favor bins above mean for small items.
    let res = post_residual as f64;
    if res < mean_residual - 20.0 {
        score += 10.0;
    } else if res > mean_residual + 20.0 {
        score -= 5.0;
    }

    // Last-chance bin: strongly prefer using it rather than leaving it for a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
        // but not if it creates a big stranded gap while next item needs space elsewhere
        if next_item_size > 0 && post_residual >= 10 && post_residual < next_item_size {
            score += 20.0;
        }
    }

    // New-bin candidate: only attractive when this item would leave a bad residual
    // in every open bin (large item with poor fit).
    if bin_residual == bin_capacity {
        if item_size >= 60 && post_residual < 20 {
            score -= 35.0; // open fresh bin for big items that fit poorly elsewhere
        } else {
            score += 45.0; // otherwise discourage opening new bins
        }
    }

    // Early in stream, slightly favor spreading into new bins to build flexibility.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if bin_residual == bin_capacity && progress < 0.15 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin (item_size : u32 , bin_residual : u32 , bin_capacity : u32 , step_index : usize , total_items : usize , open_bins_count : usize , mean_residual : f64 , next_item_size : u32 , post_residual : u32 , fitting_bins_count : usize) -> f64 {
    let cap = bin_capacity as f64 ;
    let pr = post_residual as f64 ;
    let fill_ratio = 1.0 - pr / cap ;
    let mut score = pr * 0.74 + (pr * 0.95 + fill_ratio * 0.05) * 0.26 ;

    if next_item_size > 0 {
        let nxt = next_item_size as f64 ;
        if nxt == pr {
            score -= 130.0 ;
        } else if nxt <= pr {
            let chain = pr - nxt ;
            score -= 70.0 * (1.0 - chain / cap).powi(4) ;
            if chain < 6.0 { score -= 24.0 ; }
            else if chain < 10.0 { score -= 12.0 ; }
            else if chain < 16.0 { score -= 5.0 ; }
