            else if pair as f64 >= cap - 5.0 { score -= 62.0 ; }
            else if pair as f64 >= cap - 18.0 { score -= 25.0 ; }
            else { score += 9.0 ; }
            if (next_item_size as f64) >= cap * 0.5 && fitting_bins_count > 0 { score -= 20.0 ; }
        }
