pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Penalize small dead space (wasted slivers) more than large gaps
    if post_residual > 0 {
        let frac = post_residual as f64 / bin_capacity as f64;
        if frac < 0.10 {
            score += 40.0 * (0.10 - frac);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // Lookahead: if next item fits in the post-residual, reward this bin
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 30.0 + 0.5 * next_item_size as f64;
        } else if next_item_size as f64 >= post_residual as f64
            && next_item_size as f64 <= post_residual as f64 + 20.0
        {
            // next item nearly fills this bin's leftover: mild penalty
            score += 15.0;
        }
    }

    // Tight fit reward: item fills most of the bin
    let fill = item_size as f64 / bin_residual as f64;
    score -= 60.0 * fill * fill;

    // Penalize opening new bins when many bins are already open with room
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let open_pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        score += 120.0 + 50.0 * progress + 8.0 * open_pressure;
    }

    // Prefer bins with residual close to mean residual (balanced usage)
    score += 0.15 * (bin_residual as f64 - mean_residual).abs();

    score
