pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues mod 10 (capacity 100 -> 10 classes)
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let residue = (post_residual % 10) as f64;

    // Perfect fits (residual 0 or tiny) are heavily rewarded
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Harmonic class penalty: residues in the "dead zone" (1..9) are hard to fill;
    // residue 0 (exact tenths) is good. Penalize awkward residues proportionally.
    if residue > 0.0 {
        score += residue * 1.5;
        // residue 1..=3 is nearly dead space
        if post_residual % 10 <= 3 {
            score += 8.0;
        }
    } else {
        // exact multiple of 10: reward, more so for small multiples
        score -= (20.0 - (post / 10.0).min(10.0)) * 0.8;
    }

    // Next-item lookahead: if the next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            // fraction of post_residual consumed by next item
            let fill = next_item_size as f64 / post.max(1.0);
            score -= 20.0 * fill;
            // harmonic pair: next item leaves a multiple-of-10 residual
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 12.0;
            }
        } else {
            // next item cannot use this residual at all -> mild penalty
            score += 6.0;
        }
    }

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin gets a moderate baseline so it is
    // chosen only when no open bin offers a good fit.
    if bin_residual == bin_capacity {
        score = cap * 0.55 + (item_size as f64) * 0.3;
        if fitting_bins_count <= 1 && next_item_size > 0 && next_item_size >= bin_capacity.saturating_sub(item_size) {
            score -= 10.0;
        }
    }

    // Late in the stream, prefer closing bins tightly (waste less)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (cap - post) * 0.05;

    // Prefer bins already below mean residual (consolidating waste)
    score += (mean_residual - post) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize tiny unusable gaps harshly.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward bins that can also fit the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.05 * post_residual as f64;
    } else if next_item_size > 0 {
        // Penalize blocking the next item in this bin.
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage opening new bins when few bins are open.
    if bin_residual == bin_capacity {
        score += 15.0 + 3.0 * open_bins_count as f64;
        // But opening a new bin is fine late in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    } else {
        // Mild preference for tighter existing bins.
        score += 0.02 * (bin_residual as f64 - post_residual as f64);
    }

    // Coupling with mean residual: prefer bins below mean residual (tighter).
    score += 0.05 * (mean_residual - post_residual as f64);

    score
}

