        if post_residual as i64 == next_item_size as i64 {
            score -= 40.0;
        }
        // Penalize leaving dead space that next item cannot use
        if post_residual > 0 && post_residual < next_item_size {
            score += 15.0;
        }
    } else {
        // Last item: prefer tightest fit
        score += 20.0;
    }

    // Penalize large dead space relative to mean residual
    score += 0.5 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New empty bin candidate: penalize unless nothing fits well
    if bin_residual == bin_capacity {
        score += 10.0;
        if next_item_size > 0 && post_residual as f64 >= next_item_size as f64 {
            score += 5.0;
        }
    }

    score
