        score -= 30.0;
    }

    // Lookahead coupling: if the next item fits in the post residual,
    // reward this placement (chain packing).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            // Wasted residual relative to lookahead item.
            score += 0.3 * (post_residual as f64);
        }
        // If next item exactly fills post residual, big reward.
