pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // base: prefer small post-residual, with non-linear sharpening
    let mut score = x * (1.0 + 2.0 * x * x);

    // smooth polynomial coupling with stream progress: later in stream,
    // tight fits matter more (waste becomes permanent)
    let coupling = progress * (1.0 - progress) * 4.0; // peak mid-stream
    score += 3.0 * x * x * (1.0 - coupling * 0.5);

    // last-chance bin bonus (smooth sigmoid-like via fitting_bins_count)
    let last_chance = 1.0 / (1.0 + (fitting_bins_count as f64 - 1.0).exp());
    score -= 6.0 * last_chance * (1.0 - x);

    // lookahead: if next item fits into post_residual, reward
    if next_item_size > 0 {
        let fits = (next_item_size as f64 <= pr) as i32 as f64;
        score -= 2.5 * fits * (1.0 - pr / cap);
    }

    // mean residual interaction: prefer bins near the mean (balance)
