    // new-bin candidate: neutral-ish score scaled by open bins
    if bin_residual == bin_capacity {
        score = 8.0 + 0.05 * open_bins_count as f64 + 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo 10: small residues are dead space.
    let r_mod = post_residual % 10;
    if r_mod == 0 {
        score -= 25.0; // perfectly divisible residual -> reusable by common item sizes
    } else if r_mod <= 2 {
        score += 18.0; // nearly-dead sliver
    } else if r_mod >= 8 {
        score -= 8.0;  // close to a clean class boundary
    }

    // Integer-division thresholds: residual usable by next item is valuable.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 22.0;
        // exact fit for lookahead item is excellent
        if post_residual == next_item_size {
            score -= 30.0;
        }
    } else if next_item_size > 0 {
        score += 12.0; // lookahead cannot use this residual
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize mildly so it's chosen only when fits are bad,
    // but reward it when current bin leaves a large awkward residual.
    if bin_residual == bin_capacity {
        score += 35.0;
        if post_residual > 0 && post_residual < 20 {
            score -= 20.0; // small item alone in fresh bin is fine
        }
    }

    // Prefer tighter bins: relative fill fraction via integer division classes.
    let fill_class = (bin_capacity - bin_residual) / (bin_capacity / 4);
    score -= 6.0 * fill_class as f64;

    // Late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items as f64;
    score -= 15.0 * progress * (mean_residual - post_residual as f64).max(0.0) / 10.0;

    score
}

