pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Medium gaps that few items can use are also wasteful.
    if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Perfect or near-perfect fit is highly desirable.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: reward bins whose post_residual accommodates the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // Penalize if post_residual is nonzero but too small for next item (dead space for lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Last-chance pressure: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open,
    // encourage consolidation when bin count is low.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + progress * 3.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize, especially under high open-bin pressure.
        score += 45.0 + pressure * 5.0;
        // Only open a new bin if the item would leave a big unusable gap elsewhere.
    } else {
        // Reward tight packing proportional to fill ratio.
        let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= 8.0 * fill;
    }

    // Mean residual coupling: prefer bins with residual far below mean (tighter bins).
    score += (mean_residual - bin_residual as f64) * 0.15;

    score
}

