pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: exact match of post_residual with lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: lookahead item can fit in the remaining space.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Dead space relative to the lookahead item.
        let dead = (next_item_size - post_residual) as f64;
        score += 0.5 * dead;
    }

    // Penalize residuals too small to ever be useful (below min item size 1..100 heuristic: <10).
    if post_residual < 10 {
        score += 25.0;
    }

    // Reward tightening relative to mean residual across open bins.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when existing fits are poor.
    if bin_residual == bin_capacity {
        let poor_fit = if next_item_size > 0 && post_residual >= next_item_size { 0.0 } else { 1.0 };
        score += 45.0 * (1.0 - poor_fit) + 15.0;
        // Late in the stream, prefer reusing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are excellent: reward small post_residual non-linearly.
    let fit_quality = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 35.0 * fit_quality * fit_quality;

    // Penalize dead space that cannot host the upcoming item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 12.0 + 0.5 * (next_item_size - post_residual) as f64;
        } else {
            // Reward leaving room exactly sized for the next item.
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 / (1.0 + slack * 0.08));
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // Penalize fragmenting bins relative to the crowd of alternatives.
    score += 3.0 * (fitting_bins_count as f64).ln().max(0.0);

    // Divergence from mean residual: prefer bins tighter than average when many bins open.
    let div = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * div * (open_bins_count as f64).ln().max(1.0);

    // Time horizon: early on, keep bins balanced (favor moderate residuals);
    // late in the stream, aggressively close bins (favor minimal post_residual).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * fit_quality;
    score += 10.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when current item is large and residuals are low.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        let scarcity = if next_item_size > 0 {
            (open_bins_count as f64).recip()
        } else {
            0.0
        };
        score += 25.0 - 30.0 * large_item * (1.0 - scarcity);
        // Never open a new bin for a tiny item.
        if item_size < bin_capacity / 3 {
            score += 40.0;
        }
    }

    // Small coupling: exact-fill reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;

    // Base: minimize post residual, smoothly warped
    let mut score = pr * (1.0 + 0.5 * prn * prn);

    // Non-linear coupling of post_residual with stream progress:
    // early: prefer tight fits less aggressively; late: reward tight fits more
    let progress_warp = t * t * (3.0 - 2.0 * t); // smoothstep
    score += prn * prn * (1.0 - progress_warp) * 20.0;
    score -= (cap - pr) * progress_warp * 0.3;

    // Dead-space penalty: residuals too small for typical future items
    let dead = (1.0 - prn).powi(3) * prn;
    score += dead * 30.0 * (0.5 + 0.5 * t);

    // Lookahead coupling: if next item fits post residual, reward
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits_next = (nx <= pr) as i32 as f64;
        let closeness = 1.0 - ((pr - nx).abs() / cap);
        score -= fits_next * closeness * closeness * 25.0;
        // penalize leaving exactly awkward slivers for the next item
        score += fits_next * (1.0 - closeness) * 5.0;
    }

    // Last-chance bin: strong reward to use it before opening new bins
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 - t * 0.3);
    }

    // Mean residual coupling: prefer bins below mean residual (tighter)
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * 10.0;
    score -= dev * 5.0;

    // Mild preference to keep many open bins consolidated late in stream
    score += open_bins_count as f64 * 0.1 * progress_warp;

    // New-bin candidate: penalize opening a new bin unless it's genuinely better
    if bin_residual == bin_capacity {
        score += 15.0 + 20.0 * (1.0 - progress_warp);
    }

    score
}

