        score -= 13.0;
    }
    if pr < mean_residual { score += (mean_residual - pr) * 0.27; }
    else { score -= (pr - mean_residual) * 0.09; }
    if bin_residual == bin_capacity {
        score += 16.0;
        score += progress * 14.0;
        if next_item_size > 0 {
