pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post-residual: residues that are "perfect fit"
    // classes (0, or small multiples near capacity fractions) are good ---
    let frac = post_residual as f64 / bin_capacity as f64;
    let q = post_residual / 10; // integer-division class bucket
    let r = post_residual % 10; // fine residue class

    // Reward exact-class fits (post_residual == 0 is perfect closure)
    if post_residual == 0 {
        score -= 50.0;
    } else {
        // Penalize dead space: small nonzero residuals are nearly useless
        if post_residual < 10 {
            score += 40.0;
        }
        // Harmonic bonus: residual divisible into nice classes (mod 25 / mod 20)
        if post_residual % 25 == 0 {
            score -= 8.0;
        }
        if post_residual % 20 == 0 {
            score -= 5.0;
        }
        // Fine residue: prefer round classes (r small or r near 10)
        if r <= 2 || r >= 8 {
            score -= 2.0;
        } else {
            score += 2.0;
        }
        // Fraction-of-capacity coupling: mid-range residuals (0.3..0.6 of C)
        // are the most reusable for typical items
        if frac >= 0.3 && frac <= 0.6 {
            score -= 6.0;
        } else if frac > 0.85 {
            score += 4.0; // huge leftover wastes a fresh bin slot
        }
    }

    // --- Lookahead coupling: does next_item_size fit into post_residual? ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Reward tighter lookahead fits (harmonic class of difference)
            let gap = post_residual - next_item_size;
            if gap == 0 {
                score -= 30.0; // chain closure: perfect two-item packing
            } else {
                score -= 12.0 - (gap as f64).ln() * 3.0;
                if gap % 10 == 0 {
                    score -= 3.0;
                }
            }
        } else {
            // Next item won't fit here; penalize slightly more if residual
            // would then be stranded small
            if post_residual < 10 {
                score += 15.0;
            } else {
                score += 3.0;
            }
        }
    }

    // --- Last-chance logic: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // --- New-bin candidate handling: make empty bin mildly unattractive so we
    // only open when open bins are genuinely bad fits ---
    if bin_residual == bin_capacity {
        score += 30.0;
        // Late in the stream, or when many bins are open and mean residual is
        // low, opening fresh bins is more acceptable
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * progress;
        if mean_residual < item_size as f64 {
            score -= 15.0; // no open bin really has room
        }
    }

    // --- Mild tie-break toward denser packing when many bins are open ---
    score += (open_bins_count as f64).ln() * 0.5;

    // Small deterministic jitter via harmonic hashing of post_residual class
    let h = (post_residual.wrapping_mul(2654435761) >> 13) & 7;
    score += h as f64 * 0.05;

