    // Penalize residuals too small for the smallest possible item (dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Last-chance bin: heavily favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: penalize opening bins, more so when good fits exist
    // or late in the stream where waste matters most.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let waste_penalty = 80.0 + 120.0 * progress;
        score += waste_penalty;
        // If the current bin is the only fitting bin, opening a new bin is bad.
