    }
    score * 0.93 + dead * 0.07
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let prn = pr / cap;
    let fill = 1.0 - prn;

    let mut score = pr;

    // Smooth polynomial coupling of post-residual with stream progress:
    // early stream: mild residual penalty; late stream: strong penalty on wasted space.
    let progress_coupling = 1.0 + 2.0 * progress * progress;
    score += 40.0 * prn * prn * progress_coupling;

    // Reward high fill fraction with a smooth cubic bonus in fill.
    score -= 30.0 * fill * fill * fill;

    // Dead-space penalty: residuals too small to plausibly hold future items,
    // smoothly modulated by progress.
    let dead_zone = (1.0 - prn) * (1.0 - prn) * prn; // peaks near mid residuals
    score += 20.0 * dead_zone * (0.5 + progress);

    // Last-chance bonus: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Penalize bins deviating from mean residual (keep residuals balanced).
    let dev = (pr - mean_residual) / cap;
    score += 15.0 * dev * dev;

    // Lookahead: reward residuals that can still fit the next item.
    if next_item_size > 0 {
        let fits_next = if pr >= next_item_size as f64 { 1.0 } else { 0.0 };
        score -= 12.0 * fits_next;
        // Smoothly penalize residuals just barely below the next item size.
        let gap = (next_item_size as f64 - pr) / cap;
        if gap > 0.0 {
            score += 10.0 * gap * (1.0 - gap);
        }
    }

    // Mild pressure to consolidate into fewer bins as stream progresses.
    score -= 3.0 * (open_bins_count as f64).ln().max(0.0) * progress * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post-fit residual (capacity quantized into 10-unit bands) ---
    let band = bin_capacity / 10; // 10
    let post_class = post_residual / band;          // 0..10 harmonic class
    let pre_class = bin_residual / band;

    // Reward placements that land residual into a "useful" low class (tight fill).
    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 35.0;
    } else if post_residual <= 20 {
        score -= 18.0;
    } else {
        // Dead-space penalty grows super-linearly in the leftover band.
        score += (post_class as f64 - 2.0) * 6.0;
    }

    // --- Modulo coupling: does the residual admit the lookahead item? ---
    if next_item_size > 0 && next_item_size <= post_residual {
        // Lookahead fits: reward, scaled by how "harmonically" it fits.
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 45.0; // chain of perfect fits
        } else if slack <= 10 {
            score -= 25.0;
        } else {
            score -= 10.0;
        }
        // Modulo harmonic bonus: residual divisible by next item's class
        let ncls = (next_item_size / band).max(1);
        if post_class % ncls == 0 {
            score -= 8.0;
        }
    } else if next_item_size > 0 {
        // Lookahead cannot use this bin's leftover: penalize dead space.
        score += (next_item_size as f64).min(post_residual as f64 + next_item_size as f64) * 0.15;
        score += 12.0;
    }

    // --- Integer-division thresholds on pre-class: prefer filling emptier bins first ---
    score += pre_class as f64 * 1.5;

    // --- Last-chance bin logic ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0; // must use this bin or open a new one
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing bins fit poorly
        // and the item is large relative to capacity.
        let frac = item_size as f64 / bin_capacity as f64;
        score = 100.0 - frac * 40.0;
        if fitting_bins_count == 0 {
            score -= 50.0; // no alternative
        }
        if next_item_size > 0 && next_item_size <= (bin_capacity - item_size) {
            score -= 15.0; // room for lookahead in fresh bin
        }
        if post_class <= 1 {
            score -= 10.0; // large item keeps fresh bin tight
        }
    }

    // --- Mild pressure against bin sprawl ---
    score += open_bins_count as f64 * 0.05;

    // --- Stream progression: become greedier (tighter) as stream advances ---
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));

    // Tie-break: prefer bins whose residual is near the mean (balanced packing)
    score += (bin_residual as f64 - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the next item (or any
    // realistic item) are pure waste — penalize them hard.
    let min_item = 1u32;
    let dead_threshold = next_item_size.max(min_item);
    if post_residual < dead_threshold && post_residual > 0 {
        score += 40.0 + (dead_threshold - post_residual) as f64 * 1.5;
    }
    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Tightness reward: the smaller the waste relative to the item, the better.
    let tightness = item_size as f64 / (bin_residual.max(1) as f64);
    score -= 8.0 * tightness;

    // Last-chance bin: if this is the only fitting bin, using it avoids a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // With many options, prefer bins that stay usable afterwards.
        if post_residual >= next_item_size && next_item_size > 0 {
            score -= 6.0;
        }
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer new bin
    // only when fit is bad; consolidate when few bins are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive only if this bin's fit would be poor
        // (large post_residual) or the stream is early and consolidation is cheap.
        score -= 12.0;
        score += 0.6 * pressure;
        if post_residual as f64 > mean_residual {
            score += 5.0;
        }
    } else {
        // Existing bin: mild bonus to reuse, scaled by pressure to close bins.
        score -= 2.0;
        score += 0.15 * pressure * (post_residual as f64 / bin_capacity as f64);
    }

    // Lookahead synergy: if the next item exactly fits the post residual,
    // strongly favor this placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    // Mean-residual coupling: bins far below mean residual are "ragged";
    // prefer filling bins that are already low to normalize the pool.
    let dev = mean_residual - post_residual as f64;
    score += 0.05 * dev;

    score
}

