        score += 15.0 + 20.0 * progress;
        // but allow new bin if no open bin leaves a decent residual
        if post_residual == 0 {
            score -= 25.0;
        }
    }

    // Reward exact fills of the current bin
    if post_residual == 0 {
        score -= 50.0;
    }

    // Mild penalty for leaving tiny unusable dead space (1..=5)
    if post_residual > 0 && post_residual <= 5 {
        score += 20.0;
    }

    score
}

