pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Harmonic class of post_residual: classify by decade bands (capacity fractions).
    // Dead-space bands: residuals that are very unlikely to be filled by any item.
    // Items are 1..=100, so any residual >= 1 is technically fillable, but small
    // residuals (1..=9) are the hardest to use -> heavy penalty.
    if post_residual > 0 && post_residual <= 9 {
        score += 120.0; // nearly dead space
    } else if post_residual <= 19 {
        score += 45.0;  // awkward band
    } else if post_residual <= 29 {
        score += 12.0;  // mildly awkward
    } else if post_residual >= 50 {
        // Large residuals are flexible; gently reward keeping bins "harmonic".
        score -= 25.0;
    }

    // Harmonic compatibility with the lookahead item (k=2):
    // if the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size < post_residual {
            // reward proportionally to how much of the residual the next item consumes
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 80.0 * fill;
            // penalize leaving a tiny unusable sliver after the next item too
            let post2 = post_residual - next_item_size;
            if post2 > 0 && post2 <= 9 {
                score += 60.0;
            }
        } else {
            // next item cannot use this residual at all -> the residual becomes dead
            // weight unless some later item uses it; penalize small residuals more.
            score += 30.0 + 2.0 * (100 - post_residual.min(100)) as f64;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: empty bin. Only attractive when current fit is bad.
    if bin_residual == bin_capacity {
        // Base penalty so we prefer filling existing bins when fit is decent.
        score += 150.0;
        // But if the current bin would leave a terrible residual, new bin becomes
        // competitive (subtract back).
        if post_residual > 0 && post_residual <= 19 && bin_residual < bin_capacity {
            score -= 0.0; // not applicable for the empty bin itself
        }
        // Lookahead: an empty bin can host both current and next item harmonically.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 160.0;
        }
        // Late in the stream, avoid spawning bins that likely stay near-empty.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 100.0 * progress;
        // Many open bins with high mean residual -> consolidate instead of opening.
        if mean_residual > 40.0 && open_bins_count > 3 {
            score += 50.0;
        }
    }

    // Modulo-structure bonus: residuals that are multiples of common item sizes
    // (harmonic classes) are easier to fill later.
    let pr = post_residual;
    if pr % 10 == 0 && pr > 0 {
        score -= 15.0; // round residuals align with decade-quantized items
    } else if pr % 5 == 0 && pr > 0 {
        score -= 5.0;
    }

    // Slight preference for bins whose residual is close to the mean (balance).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

