        score -= 15.0;
    } else if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 20.0; // gap unusable for next item too
    }

    // New-bin candidate: make it attractive only when current bins fit poorly.
    if bin_residual == bin_capacity {
        score += 25.0;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        if post_residual as f64 + item_size as f64 - item_size as f64 >= 0.0 && item_size as f64 > 0.7 * bin_capacity as f64 {
