    let pr = post_residual as f64;
    let mut score = pr;

    // Fractional class of post_residual: reward "harmonic" residuals that other items can reuse.
    let pr_frac = pr / cap;
    if pr == 0 {
        score -= 25.0; // perfect fit
    } else if pr_frac <= 0.10 {
        score -= 6.0; // small dead space, acceptable
    } else if pr_frac <= 0.25 {
        score += 4.0; // awkward gap zone
    } else if pr_frac <= 0.50 {
        score -= 3.0; // half-class residual, reusable by mid items
    } else {
        score -= 8.0; // large residual, very reusable
    }

    // Integer-division harmonic classes of post_residual (mod 10 buckets)
    let pr_class = (post_residual / 10) % 5;
    score -= match pr_class { 0 => 2.0, 1 => 0.0, 2 => 1.5, 3 => 0.5, _ => 1.0 };

    // Lookahead coupling: penalize if next item cannot use this bin's post_residual
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if ns > pr {
            score += 5.0 + 0.15 * (ns - pr); // next item won't fit here
            if fitting_bins_count <= 1 {
                score += 6.0; // this is the last chance bin; wasting it hurts
            }
        } else {
            score -= 4.0 + 0.10 * (pr - ns); // next item chains nicely into residual
        }
    }

    // Last-chance bonus: only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 9.0;
    }

    // New-bin candidate handling: prefer new bin only when current bins are nearly full
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_fill = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        // Reward new bin when existing bins are tight (mean residual small) or few bins open
        score -= 12.0 * (1.0 - avg_fill) + 3.0 * progress;
        if mean_residual < 20.0 {
            score -= 10.0;
        }
        if pr < 20.0 {
            score += 20.0; // would create tiny dead space in a fresh bin
        }
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let dead = 1.0 - pr / cap;
    let mut score = pr * 0.8 + dead * 4.0;

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 480.0;
    }

    // Dead-space bands calibrated to 1..=100 item sizes.
    if post_residual > 0 && post_residual <= 9 {
        score += 130.0;
    } else if post_residual <= 19 {
        score += 48.0;
    } else if post_residual <= 29 {
        score += 14.0;
    } else if post_residual >= 50 {
        score -= 22.0;
    }

    // Lookahead chain evaluation (k=2).
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if next_item_size == post_residual {
            score -= 300.0;
        } else if n < pr {
            let chain = pr - n;
            let fill = n / pr.max(1.0);
            score -= 80.0 * fill;
            if chain < 6.0 {
                score -= 25.0;
            } else if chain < 10.0 {
                score -= 12.0;
            } else if chain < 16.0 {
                score -= 5.0;
            } else if chain < 24.0 {
                score -= 2.0;
            }
            // chain residue matching current item size keeps bins harmonic
            if chain as u32 == item_size && chain < 20.0 {
                score -= 6.0;
            }
            // two-item lookahead: can next item plus a plausible pair fit?
            if item_size as f64 + n <= pr {
                score -= 4.0 * dead;
            }
        } else {
            // next item cannot use this residual -> dead weight penalty
            score += 28.0 + 0.45 * pr.min(22.0);
            if dead > 0.5 {
                score += 8.0 * dead;
            }
            if fitting_bins_count > 2 && dead > 0.4 {
                score += 3.0 * dead;
            }
        }
    } else {
        score -= 12.0;
    }

    // Tight-fit bonus: post residual barely above current item.
    let tight = (pr - item_size as f64) / cap;
    if tight >= 0.0 && tight < 0.05 {
        score -= 14.0;
    } else if tight >= 0.05 && tight < 0.12 {
        score -= 6.0;
    }

    // Last-chance bin: strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: empty bin.
    if bin_residual == bin_capacity {
        score += 150.0;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 90.0 * progress;
        if next_item_size > 0 {
            let pair = item_size + next_item_size;
            if pair == bin_capacity {
                score -= 110.0;
            } else if pair >= bin_capacity - 5 {
                score -= 65.0;
            } else if pair >= bin_capacity - 18 {
                score -= 26.0;
            } else {
                score += 9.0;
            }
            if (next_item_size as f64) >= cap * 0.5 && fitting_bins_count > 0 {
                score -= 20.0;
            }
        }
        if mean_residual > 40.0 && open_bins_count > 3 {
            score += 50.0;
        }
        if fitting_bins_count <= 2 {
            score += 7.0;
        }
        if progress > 0.66 {
            score += 26.0 * progress;
        }
    } else {
        // Consolidation pressure: prefer bins whose residual sits below mean.
        if pr < mean_residual {
            score += (mean_residual - pr) * 0.27;
        } else {
            score -= (pr - mean_residual) * 0.09;
        }
        // waste gap penalty for very dead bins above mean residual
        let waste_gap = pr - mean_residual.max(0.0);
        if waste_gap > 14.0 && dead > 0.5 && next_item_size > 0 && (next_item_size as f64) > pr * 0.8 {
            score += 0.5 * (waste_gap - 14.0).min(18.0);
        }
        // chain-friendly small residues late in the stream
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress > 0.7 && dead > 0.4 && next_item_size > 0 && (next_item_size as f64) <= pr {
            let chain = pr - next_item_size as f64;
            if chain < 4.0 {
                score -= 5.0 * progress;
            }
        }
        // many open bins with unusable residuals -> consolidate
        if dead > 0.5 && open_bins_count > 6 && next_item_size > 0 && (next_item_size as f64) > pr * 1.3 {
            score += 4.0 + 3.5 * dead;
        }
        if dead > 0.85 && next_item_size > 0 && (next_item_size as f64) <= pr {
            score -= 6.0 * dead;
        }
    }

    // Harmonic residue bonuses.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 15.0;
    } else if post_residual % 5 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    score * 0.93 + dead * 0.07
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even the
    // smallest plausible item (<= 10) are "dead space" — heavily penalize them.
    if post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 4.0;
    }

    // Penalize "awkward" residuals: gaps that can only fit very small items
    // relative to the item distribution (1..100). A residual of 1..9 is dead;
    // 10..20 is nearly dead for typical items.
    if post_residual >= 1 && post_residual <= 20 {
        score += 25.0 * (1.0 - (post_residual as f64) / 20.0);
    }

    // Reward tight fits: bonus proportional to how well the item fills the bin.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    if fill_ratio > 0.9 {
        score -= 30.0 * (fill_ratio - 0.9) / 0.1;
    } else if fill_ratio > 0.7 {
        score -= 12.0 * (fill_ratio - 0.7) / 0.2;
    }

    // Perfect fit: complete closure of the bin is highly desirable.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if the next item can exactly use the post_residual, strongly
    // favor this placement; if next item cannot fit the post residual, mild penalty.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size > post_residual {
            score += 8.0;
        } else {
            // next item fits: reward proportionally to how much it fills the gap
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        }
    }

    // Last-chance pressure: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a new bin wastes the mean residual of
    // all open bins. Penalize the new-bin candidate proportionally to the
    // aggregate wasted capacity, scaled by stream progression.
    let is_new_bin = bin_residual == bin_capacity && item_size < bin_capacity;
    if is_new_bin {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let aggregate_waste = mean_residual * open_bins_count as f64;
        score += 45.0 + aggregate_waste * 0.5 + progress * 20.0;
        // But if no open bin can fit at all, opening is unavoidable — soften.
        if fitting_bins_count == 1 {
            score -= 60.0;
        }
    }

    // Open-bins pressure: mildly discourage spreading across many bins when
    // residuals are already small (mean_residual low means bins are nearly full,
    // so prefer consolidating into the fullest usable bin).
    if !is_new_bin {
        score += open_bins_count as f64 * 0.8;
        // Favor bins tighter than average (below-mean residual => fuller bin).
        let residual_gap = mean_residual - bin_residual as f64;
        score -= residual_gap * 0.6;
    }

    score
}

