        score += 25.0;
    } else if post_residual >= 10 && post_residual < 30 {
        score += 8.0;
    }

    // Perfect closure bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 6.0;
        }
        // Penalize leaving residual that is awkwardly just below the next item.
        let gap = next_item_size as f64 - post_residual as f64;
        if gap > 0.0 && gap <= 15.0 {
            score += 10.0;
        }
    }

