    if bin_residual == bin_capacity {
        // Candidate new bin: baseline is its full capacity minus a bonus
        // that grows if open bins are heavily fragmented/low-residual.
        score = bin_capacity as f64 - 20.0 - new_bin_penalty.min(45.0);
        if fitting_bins_count == 1 {
            score += 80.0; // never open a new bin if this is the only fitting bin
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // a fresh bin is fine when the next item is also large
        }
    } else {
        // Existing bins get a slight edge over the new-bin baseline.
        score -= 5.0;
    }

    score
}

