        score += (mean_residual - pr) * 0.27;
    } else {
        score -= (pr - mean_residual) * 0.09;
    }

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate.
    if bin_residual == bin_capacity {
        score += 16.0;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 14.0;
        if next_item_size > 0 {
            let pair = item_size + next_item_size;
            if pair == bin_capacity {
                score -= 104.0;
            } else if pair >= bin_capacity.saturating_sub(5) {
                score -= 62.0;
            } else if pair >= bin_capacity.saturating_sub(18) {
                score -= 25.0;
            } else {
                score += 9.0;
            }
        }
        if progress > 0.66 {
            score += 26.0 * progress;
        }
        if fitting_bins_count <= 2 {
            score += 7.0;
        }
        if fitting_bins_count == 0 {
            score += 12.0;
        }
        // a big next item is safer in a fresh bin
        if next_item_size > 0 && (next_item_size as f64) >= cap * 0.5 && fitting_bins_count > 0 {
            score -= 20.0;
        }
        // consolidate when many bins are open with slack
        if mean_residual > 40.0 && open_bins_count > 3 {
            score += 40.0;
        }
    } else {
        // tight exact-fit lookahead on current placement
        let tight = (pr - item_size as f64) / cap;
        if tight >= 0.0 && tight < 0.05 {
            score -= 13.5;
        } else if tight >= 0.05 && tight < 0.12 {
            score -= 5.5;
        }
        // near-perfect chains
        if next_item_size > 0 && (next_item_size as f64) <= pr {
            let chain = pr - next_item_size as f64;
            if (chain / cap) < 0.02 && dead > 0.5 {
                score -= 7.5;
            }
            if chain >= 2.0 && chain <= 4.0 && dead > 0.35 && fitting_bins_count > 1 {
                score -= 3.0 * (1.0 - chain / 4.0);
            }
        }
        // moderately dead bins that next item can't chain into, scaled by gap above mean
        if dead > 0.55 && dead < 0.85 && next_item_size > 0 && (next_item_size as f64) > pr && pr > mean_residual {
            score += 1.8 * (pr - mean_residual).min(10.0) * 0.3;
        }
        // post residual exactly matching next item size (future perfect fit)
        if next_item_size > 0 && (next_item_size as f64) <= pr {
            let chain = pr - next_item_size as f64;
            if (chain as u32) == next_item_size && chain > 0.0 {
                score -= 6.0;
            }
        }
        // late-stream: prefer chains leaving tiny residuals
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress > 0.7 && dead > 0.4 && next_item_size > 0 && (next_item_size as f64) <= pr {
            let chain = pr - next_item_size as f64;
            if chain < 4.0 {
                score -= 5.0 * progress;
            }
        }
    }

    // Harmonic structure: decade/quarter-aligned residuals are easier to fill.
    let pr32 = post_residual;
    if pr32 % 10 == 0 && pr32 > 0 {
        score -= 15.0;
    } else if pr32 % 5 == 0 && pr32 > 0 {
        score -= 5.0;
    }

    // Final normalization blending raw residual and fill ratio.
    score * 0.93 + dead * 0.07
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let coupling = (1.0 + progress * progress) * (norm_pr * norm_pr) * cap;
    score += 0.5 * coupling;

    // Reward tight fits, stronger as stream progresses
    let tight = (item_size as f64 / bin_residual as f64).powi(3);
    score -= 20.0 * tight * (0.5 + progress);

    // Penalize dead space that can't fit a typical next item
    if next_item_size > 0 && (post_residual as u64) < (next_item_size as u64) {
        score += 8.0 + 12.0 * progress;
    } else if next_item_size > 0 {
        let waste = (post_residual as f64 - next_item_size as f64) / cap;
        score += 5.0 * waste * waste * cap;
    }

    // Last-chance bonus: avoid opening a new bin late in the stream
    if fitting_bins_count == 1 {
        score -= 15.0 * (0.3 + progress);
    }

    // Slight preference for bins below mean residual (keeps big bins for big items)
    score += 0.1 * (mean_residual - bin_residual as f64).abs() * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which "slot class" the leftover belongs to.
    // Classes of width 10 (min item size): class 0 = perfect/very tight fit.
    let class = post_residual / 10;
    let class_offset = post_residual % 10;

    // Reward tight fits: subtract more for smaller post_residual (non-linear).
    let tight_bonus = match class {
        0 => 60.0,
        1 => 30.0,
        2 => 12.0,
        3 => 4.0,
        _ => 0.0,
    };
    score -= tight_bonus;

    // Penalize "dead space" leftovers that no small item can use well:
    // residuals in (0,10) are pure waste; (20,30) awkward mid-class.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    if post_residual > 20 && post_residual < 30 {
        score += 8.0;
    }

    // Harmonic coupling with next item: if the next item fits exactly in the
    // post residual, strongly reward; if next item is close but not fitting, penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 50.0; // perfect chaining
            } else if slack <= 10 {
                score -= 20.0;
            } else {
                score -= 5.0;
            }
        } else {
            // Next item won't fit here: this bin becomes dead after this placement
            // unless post_residual is large enough for future small items.
            if post_residual < 20 {
                score += 30.0;
            } else {
                score += 6.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Brand-new bin candidate: penalize slightly unless current bins are crowded
    // or the fit here would be terrible.
    if bin_residual == bin_capacity {
        let mean_fit_penalty = (mean_residual - (cap - item_size as f64)).abs();
        let crowd = open_bins_count as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 - 0.8 * crowd * (1.0 - progress) - mean_fit_penalty * 0.3;
        if item_size >= 70 {
            score -= 10.0; // big items are fine in fresh bins
        }
    }

    // Small preference to keep mean residual balanced: bins far from mean get nudged.
    score += 0.15 * ((post_residual as f64 - mean_residual).abs());

    // Late-stream consolidation: near the end, prefer tighter packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 5.0;

    score
}

