pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Reward tight fits (near-perfect packing).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Reward residual that can still host a typical future item.
    if post_residual >= 10 {
        score -= 10.0;
    } else {
        score += 10.0; // dead space below min item size is pure waste
    }

    // Last-chance pressure: if this is the only fitting bin, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor filling.
    score += 0.8 * open_bins_count as f64;

    // Mean residual coupling: prefer bins below the mean residual (tighter bins)
    // to consolidate packing.
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Lookahead: if the next item fits exactly in the post-residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= 15.0 * (1.0 - gap as f64 / 10.0);
        } else {
            score -= 5.0;
        }
    }
    // If next item cannot fit in the leftover, the leftover risks becoming dead space.
    if next_item_size > post_residual && post_residual > 0 {
        score += 8.0;
    }

    // New-bin candidate handling: an empty bin should only win when no open bin
    // offers a good fit. Give it a mild baseline plus a bonus when open bins are scarce.
    if bin_residual == bin_capacity {
        score += 12.0 - 1.5 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 30.0; // must open a new bin anyway
        }
    }

    // Late-stream consolidation: near the end, prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: strongly favor bins where the item exactly fills residual.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when post_residual matches the next item size,
    // penalize when post_residual is small but unusable by the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        let diff = (pr - nxt).abs();
        if diff < 1.0 {
            score -= 500.0; // next item fits perfectly after this placement
        } else if nxt <= pr {
            score -= 100.0 * (1.0 - diff / nxt); // next item still fits
        } else {
            // dead space relative to lookahead: penalize proportionally
            score += 50.0 * (1.0 - pr / nxt).min(1.0);
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // Penalize tiny leftover slivers that likely become dead space (below min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    }

    // Compare residual against mean residual across open bins:
    // prefer placing into bins that are already relatively full (small residual).
    score += (bin_residual as f64 - mean_residual) * 0.5;

    // New-bin candidate handling: only attractive when no open bin fits well
    // or when many bins are open and fits are poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let penalty = if fitting_bins_count == 0 {
            0.0 // nothing fits anywhere, must open new bin
        } else {
            120.0 + 80.0 * progress // discourage opening new bins when fits exist
        };
        score += penalty;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is good, but dead space
    // below the minimum item size (~1) is worthless.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Penalize unusable slivers: post_residual that no plausible item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Lookahead: if the next item exactly fills the post_residual, strongly reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 25.0;
        } else if gap < 10 {
            score -= 12.0;
        } else {
            score -= 4.0 * (1.0 - gap as f64 / bin_capacity as f64);
        }
    } else if next_item_size > 0 {
        // Next item cannot use this bin's leftover: mild penalty for wasting space.
        score += 0.3 * (post_residual as f64 - mean_residual).abs();
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Crowding pressure: with many open bins, favor consolidating into
    // existing ones rather than opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let crowd = open_bins_count as f64 / 8.0;
    score += crowd * (1.0 - progress) * 2.0;

    // New-bin candidate handling: an empty bin should only win when no open
    // bin offers a decent fit. Penalize the fresh bin by its "pristine waste".
    if bin_residual == bin_capacity {
        let mean_gap = (mean_residual - item_size as f64).max(0.0);
        // If open bins are on average roomy, opening new is less harmful.
        score += 15.0 + 0.5 * item_size as f64 - 0.4 * mean_gap;
        // Late in the stream, avoid opening bins for small leftovers.
        score += 10.0 * progress;
    } else {
        // Prefer bins whose residual is close to mean (keep balance) slightly.
        score += 0.1 * (bin_residual as f64 - mean_residual).abs();
    }

    // Mild preference for fuller bins overall (best-fit flavor).
    score += 0.05 * (bin_capacity - bin_residual) as f64;

