    score *= tighten;

    // Dead-space penalty: residuals too small for any item are wasted
    if pr > 0 && pr < 10 {
        score += 25.0 * (1.0 - pr as f64 / 10.0);
    }

    // Lookahead synergy: reward if next item can fit in the post-residual
    if next_item_size > 0 && post_residual >= next_item_size {
        let snug = 1.0 - (post_residual - next_item_size) as f64 / cap;
        score -= 8.0 * snug * (0.5 + progress);
    } else if next_item_size > 0 {
        // penalize blocking the next item
        score += 4.0 * (next_item_size as f64 / cap);
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0 + 15.0 * progress;
    }

    // New empty bin candidate: penalize, more so early in stream;
    // relax penalty late when fragmentation dominates
    if bin_residual == bin_capacity {
        let relax = progress * progress * 0.6;
        score += (30.0 - 30.0 * relax).max(2.0);
        if fitting_bins_count == 0 {
            score -= 40.0; // no open bin fits, must open
        }
    }

    // Mild preference to use fuller bins relative to fleet mean
    score -= 2.0 * (1.0 - bin_residual as f64 / cap) * (1.0 + mean_residual / cap);

    score
