    let mut score = post_residual as f64;

    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of the leftover: small leftovers (1..=9) are near-dead space,
    // reward hitting them; mid leftovers (10..=29) are reusable for small items.
    let pr = post_residual;
    if pr > 0 && pr <= 9 {
        score -= 5.0; // near-perfect fit, tiny dead space
    } else if pr <= 29 {
        score -= 2.0;
    } else if pr <= 49 {
        score += 1.5; // awkward class, half-bin leftover
    } else {
        score += 3.0; // large leftover: wasteful placement
    }

