pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to hold typical
    // future items are wasted capacity. Penalize the "unusable zone".
    let dead_threshold = 20.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 4.0;
    }

    // Reward tight fits strongly (post_residual near 0 is excellent).
    score -= (1.0 - (post_residual as f64) / (bin_capacity as f64)).powi(6) * 30.0;

    // Pressure from number of open bins: when many bins are open,
    // prefer consolidating into existing bins (penalize opening new ones).
    let open_pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // Candidate for a brand-new bin.
        score += open_pressure * 3.0;
        // If this is a last-chance situation for an existing bin, make
        // opening a new bin less attractive.
        if fitting_bins_count <= 1 {
            score += 25.0;
        }
        // If the item would leave a large awkward gap in a new bin,
        // mildly discourage it.
        score += (post_residual as f64) * 0.15;
    } else {
        // Existing bin: reward being one of few fitting options,
        // especially last-chance bins.
        if fitting_bins_count == 1 {
            score -= 20.0;
        } else if fitting_bins_count <= 3 {
            score -= 5.0;
        }
        // Slight preference for bins with smaller residual (best-fit flavor)
        score += (bin_residual as f64) * 0.05;
    }

    // Lookahead: if next item fits exactly into the post_residual,
    // this placement is very desirable.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    }
    // If next item cannot fit into post_residual but would fit a fresh bin,
    // penalize leaving a gap that blocks the next item.
    if next_item_size > post_residual && next_item_size > 0 && post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Stream progression: late in the stream, be more conservative with
    // opening new bins.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if bin_residual == bin_capacity {
            score += progress * 10.0;
        }
    }

    // Slight penalty if this bin's residual is far below the mean residual
    // (already well-packed bins should keep absorbing items).
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-perfect match: next item fits with small leftover.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Next item does NOT fit here: penalize proportionally to wasted opportunity.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 10.0 + 0.3 * (next_item_size - post_residual) as f64;
    }

    // Penalize creating tiny unusable dead space (hard-to-fill slivers).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Prefer bins tighter than the mean residual (best-fit behavior).
    score -= 0.4 * (mean_residual - bin_residual as f64);

    // Mild pressure against accumulating many open bins early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // Brand-new empty bin: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 8.0 + 0.1 * open_bins_count as f64;
        if fitting_bins_count > 1 {
            score += 20.0;
        }
    }

    score
}

